// ---- src/service/20-http.js
// HTTP API on 127.0.0.1:PORT. The spike page is a file:// document (origin "null"), so
// every response allows any origin and is loadable under COEP require-corp.
var fileDir = null;             // directory of the files served on /file/<name>
var FILE_ALLOW = [SYNTHETIC_NAME];
var openHandler = null;         // set once the spike is installed

function setCors(res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Range');
  res.setHeader('Access-Control-Expose-Headers', 'Content-Range, Content-Length');
  res.setHeader('Cross-Origin-Resource-Policy', 'cross-origin');
}

function sendJson(res, code, obj) {
  var body = JSON.stringify(obj);
  res.writeHead(code, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function readBody(req, limit, cb) {
  var chunks = [], size = 0, done = false;
  req.on('data', function (chunk) {
    if (done) return;
    size += chunk.length;
    if (size > limit) { done = true; cb(new Error('body larger than ' + limit + ' bytes')); return; }
    chunks.push(chunk);
  });
  req.on('end', function () { if (!done) { done = true; cb(null, Buffer.concat(chunks).toString('utf8')); } });
  req.on('error', function (e) { if (!done) { done = true; cb(e); } });
}

// Only "bytes=a-b" and "bytes=a-"; anything else is unsatisfiable.
function parseRange(header, size) {
  var m = /^bytes=(\d+)-(\d*)$/.exec(header || '');
  if (!m) return null;
  var start = Number(m[1]);
  var end = m[2] === '' ? size - 1 : Math.min(Number(m[2]), size - 1);
  if (start >= size || start > end) return null;
  return { start: start, end: end };
}

function serveFile(req, res, name) {
  if (!fileDir || FILE_ALLOW.indexOf(name) < 0) return sendJson(res, 404, { error: 'not found: ' + name });
  var file = path.join(fileDir, name);
  fs.stat(file, function (err, st) {
    if (err) return sendJson(res, 404, { error: 'not found: ' + name });
    var headers = { 'Content-Type': 'application/octet-stream', 'Accept-Ranges': 'bytes' };
    if (req.headers.range) {
      var r = parseRange(req.headers.range, st.size);
      if (!r) {
        res.writeHead(416, { 'Content-Range': 'bytes */' + st.size });
        return res.end();
      }
      headers['Content-Range'] = 'bytes ' + r.start + '-' + r.end + '/' + st.size;
      headers['Content-Length'] = r.end - r.start + 1;
      res.writeHead(206, headers);
      return pipeFile(fs.createReadStream(file, { start: r.start, end: r.end }), res);
    }
    headers['Content-Length'] = st.size;
    res.writeHead(200, headers);
    pipeFile(fs.createReadStream(file), res);
  });
}

// A read error after the headers went out can only cut the response short; a client that
// goes away early must not leave the file open.
function pipeFile(stream, res) {
  stream.on('error', function (e) {
    log('read error: ' + e.message);
    res.destroy();
  });
  res.on('close', function () { stream.destroy(); });
  stream.pipe(res);
}

function handle(req, res) {
  setCors(res);
  var url = req.url.split('?')[0];
  if (req.method === 'OPTIONS') { res.writeHead(204); return res.end(); }
  if (req.method === 'GET' && url === '/status') return sendJson(res, 200, status);
  if (req.method === 'POST' && url === '/report') {
    return readBody(req, 65536, function (err, text) {
      if (err) return sendJson(res, 413, { error: err.message });
      var report;
      try { report = JSON.parse(text); } catch (e) { report = null; }
      if (!report || typeof report !== 'object' || Array.isArray(report)) {
        return sendJson(res, 400, { error: 'body must be a JSON object' });
      }
      report.at = new Date().toISOString();
      addReport(report);
      res.writeHead(204);
      res.end();
    });
  }
  if (req.method === 'POST' && url === '/open') {
    if (!openHandler) return sendJson(res, 409, { error: 'not ready' });
    openHandler();
    return sendJson(res, 202, { opening: true });
  }
  if (req.method === 'GET' && url.indexOf('/file/') === 0) {
    var name;
    try { name = decodeURIComponent(url.slice('/file/'.length)); } catch (e) {
      return sendJson(res, 400, { error: 'bad file name' });
    }
    return serveFile(req, res, name);
  }
  sendJson(res, 404, { error: 'not found' });
}

var server = http.createServer(handle);

// ---- src/service/30-install.js
// Installing the spike: the pinned th08-web build, the spike pages and a synthetic file.

// GET into memory, following redirects (GitHub release assets redirect to a CDN).
function download(url, redirects) {
  redirects = redirects || 0;
  return new Promise(function (resolve, reject) {
    var opts = urlLib.parse(url);
    opts.headers = { 'User-Agent': 'tizenbrew-th08' };
    var req = (opts.protocol === 'https:' ? https : http).get(opts, function (res) {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        res.resume();
        if (redirects >= 5) return reject(new Error('too many redirects: ' + url));
        return resolve(download(urlLib.resolve(url, res.headers.location), redirects + 1));
      }
      if (res.statusCode !== 200) {
        res.resume();
        return reject(new Error('HTTP ' + res.statusCode + ' for ' + url));
      }
      var chunks = [];
      res.on('data', function (c) { chunks.push(c); });
      res.on('end', function () { resolve(Buffer.concat(chunks)); });
      res.on('error', reject);
    });
    req.setTimeout(30000, function () { req.abort(); reject(new Error('no answer for 30 s: ' + url)); });
    req.on('error', reject);
  });
}

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

// Regular files of a ustar archive, by path without a leading "./".
function untar(tarBuf) {
  var out = {}, off = 0;
  while (off + 512 <= tarBuf.length) {
    var header = tarBuf.slice(off, off + 512);
    if (header[0] === 0) break;
    var name = header.slice(0, 100).toString('utf8').replace(/\0[\s\S]*$/, '');
    var prefix = header.slice(345, 500).toString('utf8').replace(/\0[\s\S]*$/, '');
    if (prefix) name = prefix + '/' + name;
    var size = parseInt(header.slice(124, 136).toString('ascii').replace(/\0[\s\S]*$/, '').trim() || '0', 8);
    var type = header[156];
    off += 512;
    if (type === 0 || type === 48) out[name.replace(/^\.\//, '')] = tarBuf.slice(off, off + size);
    off += Math.ceil(size / 512) * 512;
  }
  return out;
}

function mkdirp(dir) {
  if (fs.existsSync(dir)) return;
  mkdirp(path.dirname(dir));
  fs.mkdirSync(dir);
}

function writeAtomic(file, buf) {
  fs.writeFileSync(file + '.part', buf);
  fs.renameSync(file + '.part', file);
}

function readText(file) {
  try { return fs.readFileSync(file, 'utf8'); } catch (e) { return null; }
}

// Byte i is i mod 251, so any slice can be checked without the file.
function syntheticBytes(size) {
  var buf = Buffer.alloc(size);
  for (var i = 0; i < size; i++) buf[i] = i % 251;
  return buf;
}

function installBuild(dir) {
  log('download ' + BUILD_URL);
  return download(BUILD_URL).then(function (gz) {
    var got = sha256(gz);
    if (got !== BUILD_SHA256) throw new Error('build sha256 mismatch: expected ' + BUILD_SHA256 + ', got ' + got);
    var entries = untar(zlib.gunzipSync(gz));
    BUILD_FILES.forEach(function (name) {
      if (!entries[name] || !entries[name].length) throw new Error('build archive has no (or an empty) ' + name);
      writeAtomic(path.join(dir, name), entries[name]);
    });
  });
}

function installAssets(dir) {
  return ASSET_FILES.reduce(function (chain, name) {
    return chain.then(function () {
      log('download ' + ASSET_BASE + name);
      return download(ASSET_BASE + name).then(function (buf) {
        if (!buf.length) throw new Error('empty download: ' + ASSET_BASE + name);
        writeAtomic(path.join(dir, name), buf);
      });
    });
  }, Promise.resolve());
}

function fileSize(file) {
  try { return fs.statSync(file).size; } catch (e) { return -1; }
}

// Installed = this version's marker plus every expected file (synthetic.bin at full size).
function spikeComplete(dir) {
  if (readText(path.join(dir, '.complete')) !== VERSION) return false;
  var names = BUILD_FILES.concat(ASSET_FILES);
  for (var i = 0; i < names.length; i++) {
    if (fileSize(path.join(dir, names[i])) <= 0) return false;
  }
  return fileSize(path.join(dir, SYNTHETIC_NAME)) === SYNTHETIC_SIZE;
}

// Resolves the spike directory and installs into it unless it is complete. Milestone-0
// exception to the spec's staged activation: the spike holds no user data, so recovery from
// an interrupted install is a full reinstall (~1.7 MB). The stale marker goes first and the
// new one is written last.
function install() {
  checkNode();
  var base = resolveDataDir();
  var dir = path.join(base, 'th08', 'spike');
  var marker = path.join(dir, '.complete');
  status.dataDir = base;
  status.launcherUrl = 'file://' + path.join(dir, 'spike.html');
  mkdirp(dir);
  fileDir = dir;
  if (spikeComplete(dir)) return Promise.resolve();
  if (fs.existsSync(marker)) fs.unlinkSync(marker);
  status.state = 'installing';
  status.progress = 'th08-web build';
  return installBuild(dir).then(function () {
    status.progress = 'spike pages';
    return installAssets(dir);
  }).then(function () {
    status.progress = 'synthetic file';
    writeAtomic(path.join(dir, SYNTHETIC_NAME), syntheticBytes(SYNTHETIC_SIZE));
    writeAtomic(marker, Buffer.from(VERSION));
    status.progress = '';
  });
}

// ---- src/service/50-main.js
server.on('error', function (e) {
  status.state = 'error';
  status.error = 'port ' + PORT + ': ' + e.message;
});

server.listen(PORT, '127.0.0.1', function () {
  Promise.resolve().then(install).then(function () {
    status.state = 'ready';
    log('ready');
  }, function (e) {
    status.state = 'error';
    status.error = e.message;
    log('install failed: ' + e.message);
  });
});

